INSERT INTO `job_translations` (`id`, `job_id`, `language_code`, `job_title`, `description`, `requirements`, `responsibilities`, `benefits`) VALUES
(0, 3, 'ar', 'نن', 'نن', 'نن', 'نن', 'نن'),
(1, 1, 'en', 'Senior Full Stack Developer', 'We are looking for an experienced Full Stack Developer to join our growing tech team.', '- 5+ years of experience in web development\n- Strong knowledge of React, Node.js, MongoDB\n- Experience with AWS/Azure\n- Bachelor degree in Computer Science', '- Develop and maintain web applications\n- Write clean, maintainable code\n- Collaborate with design and product teams\n- Mentor junior developers', '- Competitive salary\n- Health insurance\n- Remote work option\n- Annual bonus\n- Professional development budget'),
(2, 1, 'ar', 'مطور Full Stack أول', 'نبحث عن مطور Full Stack ذو خبرة للانضمام لفريق التقنية المتنامي لدينا.', '- خبرة 5+ سنوات في تطوير الويب\n- معرفة قوية بـ React و Node.js و MongoDB\n- خبرة مع AWS/Azure\n- درجة بكالوريوس في علوم الحاسب', '- تطوير وصيانة تطبيقات الويب\n- كتابة كود نظيف وقابل للصيانة\n- التعاون مع فرق التصميم والمنتج\n- توجيه المطورين المبتدئين', '- راتب تنافسي\n- تأمين صحي\n- خيار العمل عن بُعد\n- مكافأة سنوية\n- ميزانية تطوير مهني'),
(3, 2, 'en', 'Digital Marketing Manager', 'Manage our digital marketing campaigns and grow our online presence.', '- 3+ years in digital marketing\n- SEO/SEM expertise\n- Social media marketing\n- Google Analytics certified', '- Plan and execute digital campaigns\n- Manage social media channels\n- Analyze campaign performance\n- Budget management', '- Competitive salary\n- Performance bonus\n- Health insurance\n- Training opportunities'),
(4, 2, 'ar', 'مدير التسويق الرقمي', 'إدارة حملات التسويق الرقمي وتنمية تواجدنا الإلكتروني.', '- خبرة 3+ سنوات في التسويق الرقمي\n- خبرة في SEO/SEM\n- تسويق عبر وسائل التواصل\n- شهادة Google Analytics', '- تخطيط وتنفيذ الحملات الرقمية\n- إدارة قنوات التواصل الاجتماعي\n- تحليل أداء الحملات\n- إدارة الميزانية', '- راتب تنافسي\n- مكافأة أداء\n- تأمين صحي\n- فرص تدريب');
